        if(x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2){const auto&q=x.ops[1];if(q.type==ZYDIS_OPERAND_TYPE_REGISTER){cur=large(q.reg.value);continue;}if(q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE){auto v=q.imm.value.u;if(x.ops[0].size==64&&q.size==32)v=static_cast<std::uint64_t>(static_cast<std::int64_t>(static_cast<std::int32_t>(v)));out.ok=true;out.value=v;out.source="IMM";return out;}}
