    Rc4Sem f;f.begin=rf.begin_rva;f.end=rf.end_rva;auto off=rvaoff(pe,rf.begin_rva,d.size());if(!off||rf.end_rva<=rf.begin_rva)return f;ZydisDecoder dec;if(!ZYAN_SUCCESS(ZydisDecoderInit(&dec,ZYDIS_MACHINE_MODE_LONG_64,ZYDIS_STACK_WIDTH_64)))return f;
