std::optional<std::string> wide_ascii_ptr(std::span<const std::uint8_t>d,const PeInfo&pe,const Ptr&p,std::size_t max_chars=128){if(!p.ok||p.stack||p.stack_load||p.va<pe.image_base||p.va-pe.image_base>0xffffffffull)return{};auto r=static_cast<std::uint32_t>(p.va-pe.image_base);auto o=rvaoff(pe,r,d.size());if(!o)return{};std::string s;for(std::size_t i=0;i<max_chars&&*o+i*2+2<=d.size();++i){auto c=std::uint16_t(d[*o+i*2])|(std::uint16_t(d[*o+i*2+1])<<8);if(!c)return s;if(c<0x20||c>0x7e)return{};s.push_back(static_cast<char>(c));}return{};}
std::optional<std::string> ascii_ptr(std::span<const std::uint8_t>d,const PeInfo&pe,const Ptr&p,std::size_t max_chars=128){if(!p.ok||p.stack||p.stack_load||p.va<pe.image_base||p.va-pe.image_base>0xffffffffull)return{};auto r=static_cast<std::uint32_t>(p.va-pe.image_base);auto o=rvaoff(pe,r,d.size());if(!o)return{};std::string s;for(std::size_t i=0;i<max_chars&&*o+i<d.size();++i){auto c=d[*o+i];if(!c)return s;if(c<0x20||c>0x7e)return{};s.push_back(static_cast<char>(c));}return{};}
