std::optional<std::pair<std::string,std::uint32_t>> cryptoapi_aes_alg(std::uint32_t alg){if(alg==0x660e)return std::pair<std::string,std::uint32_t>{"AES-128",16};if(alg==0x660f)return std::pair<std::string,std::uint32_t>{"AES-192",24};if(alg==0x6610)return std::pair<std::string,std::uint32_t>{"AES-256",32};return{};}
