std::optional<EvpSelection> resolve_evp_selection(std::span<const std::uint8_t>d,const PeInfo&pe,const ImportedCall&init,const std::vector<ImportedCall>&calls){auto origin=imported_return_origin_info(d,pe,init.callsite_rva,1,calls);if(!origin)return{};if(evp_cipher(origin->name))return EvpSelection{origin->name,origin->name};const ImportedCall*src=nullptr;for(const auto&c:calls)if(c.callsite_rva==origin->callsite_rva){src=&c;break;}if(!src)return{};if(origin->name=="EVP_get_cipherbyname"){auto p=resolve_win64_pointer_arg(d,pe,src->callsite_rva,0);auto name=ascii_ptr(d,pe,p);if(!name||!evp_cipher(*name))return{};return EvpSelection{*name,"EVP_get_cipherbyname(\""+*name+"\")"};}if(origin->name=="EVP_CIPHER_fetch"){auto p=resolve_win64_pointer_arg(d,pe,src->callsite_rva,1);auto name=ascii_ptr(d,pe,p);if(!name||!evp_cipher(*name))return{};return EvpSelection{*name,"EVP_CIPHER_fetch(\""+*name+"\")"};}return{};}
