    if(zi.mnemonic==ZYDIS_MNEMONIC_MOV&&zi.operand_count_visible>=2&&ops[1].type==ZYDIS_OPERAND_TYPE_REGISTER){auto it=orig.find(large(ops[1].reg.value));if(it!=orig.end())n=it->second;}
    else if(zi.mnemonic==ZYDIS_MNEMONIC_MOV&&zi.operand_count_visible>=2&&ops[1].type==ZYDIS_OPERAND_TYPE_MEMORY&&ops[1].mem.index==ZYDIS_REGISTER_NONE&&(large(ops[1].mem.base)==ZYDIS_REGISTER_RSP||large(ops[1].mem.base)==ZYDIS_REGISTER_RBP)){auto k=std::make_pair(large(ops[1].mem.base),ops[1].mem.disp.has_displacement?ops[1].mem.disp.value:0);auto it=stack_orig.find(k);if(it!=stack_orig.end())n=it->second;}
    else if(zi.mnemonic==ZYDIS_MNEMONIC_LEA&&zi.operand_count_visible>=2&&ops[1].type==ZYDIS_OPERAND_TYPE_MEMORY){auto it=orig.find(large(ops[1].mem.base));if(it!=orig.end()){n=it->second;n->delta+=ops[1].mem.disp.has_displacement?ops[1].mem.disp.value:0;if(ops[1].mem.index!=ZYDIS_REGISTER_NONE)n->dynamic=true;}}
