bool same_pointer_object(const Ptr&a,const Ptr&b){if(!a.ok||!b.ok)return false;if((a.stack||a.stack_load)&&(b.stack||b.stack_load))return a.stack_base==b.stack_base&&a.stack_disp==b.stack_disp;if(!a.stack&&!a.stack_load&&!b.stack&&!b.stack_load)return a.va==b.va;return false;}
